templates.react:
export function ExportAction({
  format = "{{format}}",
  fileName = "{{fileName}}",
  rowCount = "{{rowCount}}",
  includeHeaders = {{includeHeaders}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 280, padding: "16px 18px", borderRadius: 12, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <p style={{ margin: "0 0 4px", fontWeight: 700 }}>Export {rowCount}</p>
      <p style={{ margin: "0 0 8px", fontSize: 12, color: "#24143099", fontVariantNumeric: "tabular-nums" }}>{fileName}.<span style={{ textTransform: "uppercase", fontWeight: 700 }}>{format}</span></p>
      {includeHeaders && <p style={{ margin: "0 0 12px", fontSize: 11, color: "#24143088" }}>Column headers included on row 1.</p>}
      <button type="button" style={{ width: "100%", padding: 10, borderRadius: 8, border: "none", background: accent, color: "#14351f", fontWeight: 700, cursor: "pointer", marginTop: 6 }}>Export as {format}</button>
    </div>
  );
}
